class Solution:
    def minDeletion(self, nums: List[int]) -> int:
        kept = []
        for x in nums:
            if len(kept) % 2 == 1 and kept[-1] == x:
                continue
            kept.append(x)
        return len(nums) - len(kept) + len(kept) % 2

