class Solution {
public:
    int minDeletion(vector<int>& nums) {
        vector<int> kept;
        kept.reserve(nums.size());
        for (int x : nums) {
            if (kept.size() % 2 == 1 && kept.back() == x) continue;
            kept.push_back(x);
        }
        return (int)nums.size() - (int)kept.size() + (int)(kept.size() % 2);
    }
};

