class Solution {
    public int minDeletion(int[] nums) {
        List<Integer> kept = new ArrayList<>();
        for (int x : nums) {
            if (kept.size() % 2 == 1 && kept.get(kept.size() - 1) == x) continue;
            kept.add(x);
        }
        return nums.length - kept.size() + kept.size() % 2;
    }
};

