class Solution {
public:
    int minDeletion(vector<int>& nums) {
        int kept = 0, prev = 0;
        for (int x : nums) {
            if ((kept & 1) == 1 && prev == x) continue;
            kept++;
            prev = x;
        }
        return (int)nums.size() - kept + (kept & 1);
    }
};

